mapper.select:
SELECT ACCT_NO id, ACCT_NAME text, CCY object /*多级法人改造，增加FIN_PRODUCT.FINPROD_ID查询字段 add by caojin 2020/6/14 start */ ,SEQ_NO seqNo /*多级法人改造，增加FIN_PRODUCT.FINPROD_ID查询字段 add by caojin 2020/6/14 end */ FROM STL_CAPACCT_INFO
WHERE ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')) OR ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%'))
WHERE ACCT_NO = #{initValue}

SELECT DISTINCT FEE_ID id, FEE_NAME text FROM MST_FEEINFO
AND ( FEE_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR FEE_NAME LIKE CONCAT('%',CONCAT(#{search},'%')) )
AND FEE_ID = #{initValue}
AND APPLY_TYPE = #{applyType}
AND FEE_TYPE in
#{item}

SELECT COUNTER_ID, COUNTER_TYPE, COUNTER_NAME FROM MST_COUNTER_PARTY
COUNTER_TYPE = '01'
AND LINK_ID = #{customerId,jdbcType=VARCHAR}

SELECT DISTINCT mcci.PARTY_ID id, mcci.PARTY_ABBR text FROM MST_CFETS_CUSTOMER_INFO mcci WHERE 1 = 1
AND mcci.PARTY_ID NOT IN (SELECT PARTY_ID FROM MST_COUNTER_PARTY WHERE PARTY_ID IS NOT NULL)
AND (mcci.PARTY_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR mcci.PARTY_CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR mcci.PARTY_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR mcci.PARTY_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
OR mcci.PARTY_ID = #{initValue,jdbcType=VARCHAR}
OR mcci.PARTY_ID = #{partyId,jdbcType=VARCHAR}
